def twoSum(nums, target):
    d = {}
    for i, x in enumerate(nums):
        if target - x in d:
            return [d[target-x], i]
        d[x] = i
    return []

class Solution:
    def reverseList(self, head):
        pre = None
        cur = head
        while cur:
            nxt = cur.next
            cur.next = pre
            pre = cur
            cur = nxt
        return pre

def longestPalindrome(s):
    def expand(l, r):
        while l>=0 and r<len(s) and s[l]==s[r]:
            l -= 1; r += 1
        return l+1, r-1
    L = R = 0
    for i in range(len(s)):
        l1, r1 = expand(i, i)
        l2, r2 = expand(i, i+1)
        if r1-l1 > R-L: L, R = l1, r1
        if r2-l2 > R-L: L, R = l2, r2
    return s[L:R+1]

