def climbStairs(n):
    a, b = 1, 1
    for _ in range(n-1):
        a, b = b, a+b
    return b

def levelOrder(root):
    if not root: return []
    from collections import deque
    q = deque([root])
    res = []
    while q:
        size = len(q)
        level = []
        for _ in range(size):
            node = q.popleft()
            level.append(node.val)
            if node.left:  q.append(node.left)
            if node.right: q.append(node.right)
        res.append(level)
    return res

def lengthOfLongestSubstring(s):
    d, l, ans = {}, 0, 0
    for r, c in enumerate(s):
        if c in d and d[c] >= l:
            l = d[c] + 1
        d[c] = r
        ans = max(ans, r-l+1)
    return ans
